-- Aquagram — 0052: Tür görselleri 8. parti (233–268 arası 36 tür, 46 görsel)
update public.species s set images = (select array_agg('https://aquagram.com.tr/media/tur/' || v.slug || '-' || i || '.webp' order by i) from generate_series(1, v.adet) i)
from (values ('pseudosphromenus-dayi',2),('sphaerichthys-osphromenoides',1),('sphaerichthys-selatanensis',1),('sphaerichthys-vaillanti',2),('trichogaster-chuna',2),('trichogaster-fasciata',1),('trichogaster-labiosa',1),('trichogaster-lalius',1),('trichopodus-leerii',1),('trichopodus-microlepis',1),('trichopodus-trichopterus',1),('trichopsis-pumila',2),('trichopsis-vittata',1),('alestopetersius-brichardi',1),('aphyocharax-anisitsi',1),('aphyocharax-paraguayensis',1),('arnoldichthys-spilopterus',2),('boehlkea-fredcochui',1),('ctenolucius-hujeta',1),('exodon-paradoxus',3),('gymnocorymbus-ternetzi',1),('hasemania-nana',1),('hemigrammus-bleheri',1),('hemigrammus-erythrozonus',2),('hemigrammus-ocellifer',1),('hydrocynus-vittatus',1),('hydrolycus-scomberoides',1),('hyphessobrycon-amandae',2),('hyphessobrycon-amapaensis',2),('hyphessobrycon-columbianus',1),('hyphessobrycon-eques',1),('hyphessobrycon-erythrostigma',1),('hyphessobrycon-flammeus',1),('hyphessobrycon-heliacus',1),('hyphessobrycon-herbertaxelrodi',1),('hyphessobrycon-megalopterus',1)) as v(slug, adet)
where s.slug = v.slug;
